#!/bin/python

import math
import os
import random
import re
import sys

class Solution:
    def subsequenceCount(self, n, k, x):
        return pow(2, k) * (pow(2, k) - 1) // 2 - self.find_missing_subsequences(n, k, x)

    def find_missing_subsequences(self, n, k, x):
        if n == 1:
            return 1

        low, high = 1, 2**k
        while low < high:
            mid = (low + high) // 2
            subsets = self.subsetCount(mid, k)
            if subsets == n: 
                minimum, maximum = mid, mid + (2**k - 1) // 2 + 1
                low, high = minimum, high if maximum < 2**(k + 1) else low if minimum < 2**k else maximum
            elif subsets < n:
                high = mid
            elif subsets > n:
                low = mid + 1

        missing_subsequences = 2**(k - low)
        if n == 2**(k - low) + 1:
            return max(1, missing_subsequences - 2)
        elif n == 2**(k - low):
            return missing_subsequences
        else:
            return 0

    def subsetCount(self, m, k):
        # The number of subsets with a given XOR of x is equal to m's 2**kth smallest number
        # Plus 1
        index = m >> k
        xy = index // 2**k + 1
        a = m % 2**k + 1
        return math.binomial(k + xy - 1, xy - 1) + a


