    edges = list(itertools.chain.from_iterable(itertools.combinations(range(1, n+1), 2)))
    edges = random.sample(edges, len(edges))
    current = set()

    def dfs(v):
        current.add(v)
        for u in range(1, n+1):
            if u not in current and (v, u) in edges or (u, v) in edges:
                dfs(u)

    dfs(1)
    result = [0] * n
    for v in current:
