from typing import List

def find_kth_beaded_string(n: int, k: int) -> int:
    def is_bead(i: int, color: int) -> bool:
        return i == 0 or (i - 1) % n != (i % n)

    if k == 1:
        return 0

    if k % n == 1:
        return 0

    # If k is greater than the first k-1 beads plus the first bead itself
    if k > (n - 1) + 1:
        if k % (n - 1) == 1:
            return 0

    for i in range(1, n-1):
        if k // n + (1 if k % n else 0) == i:
            return i

    return -1

