# Calculate the jelliness of the cobweb
@cache
def dp(start, end, rem, rem_even, rem_odd, total_sum):
    total_sum %= 1000000007
    if start == end:
        return 1

    products = []
    for u, v, x, color in edges[1:]:
        if (u != start or v != end) and abs(u - v) == 1:
            new_start, new_end, new_rem, new_total_sum = start, end, rem - ((color == 0) * 2), total_sum
            if color == 0:
                new_end += 1
            else:
                new_start += 1
            products.append(new_rem_even * new_rem_odd * new_total_sum * dp(new_start, new_end, new_rem, new_rem_even, new_rem_odd, total_sum) % 1000000007)

    if not products:
        return 0
    else:
        return max(products) % 1000000007

# Main function to solve the problem
def solve():
    n, edges = parse_input()
    global edges_modifiable_colors
    edges_filter = [edge[3] for edge in edges]
    edges_set = set(tuple(edge) for edge in edges)
    for edge in edges:
        for i, e in enumerate(edges[1:]):
            if tuple(e) != set(edge) and e not in edges_filter and e[3] != 1:
                edges_set.remove(tuple(edge))
    global edges_modifiable_colors
    edges_modifiable_colors = 0
    for edge in edges:
        if edge[3] != 1:
            edges_modifiable_colors += 1

    result = dp(start='0', end='n - 1', rem='0', rem_even='0', rem_odd='0', total_sum='1')
    result %= 1000000007
    if result == 0:
        result = 1

    return result

