def max_melody_length(notes):
    prefix_sum = [0] * (n + 1)
    for i, note in enumerate(notes):
        prefix_sum[i + 1] = prefix_sum[i] + note

    memo = {}

    def dp(index, previous_note, remainder):
        if index == n + 1:
            return 0
        if (index, previous_note) in memo:
            return memo[(index, previous_note)]

        max_length = 0
        for next_note in notes[index:]:
            if (next_note - previous_note) % 7 != 0:
                max_length = max(max_length, dp(index + 1, next_note, remainder))
            elif next_note - remainder == 1 or next_note - remainder == 6:
                max_length = max(max_length, dp(index + 1, next_note, remainder) + 1)

        memo[(index, previous_note)] = max_length
        return max_length

    return max(dp(1, notes[0], i) for i in range(1, 7))

