import heapq

def zorg_get_necklace(n, k):
    numbers = [0, 1]
    heap = []
    for number in numbers:
        for _ in range(n):
            heapq.heappush(heap, (number, [number]))

    target_index = k - 1
    result = []
    while heap:
        while target_index >= 0 and heap and (not result or heap[0][0] < result[-1][0]):
            result.append(heapq.heappop(heap)[1])

        if heap and target_index >= len(heap[0]):
            target_index -= len(heap[0])

        if not heap or target_index < 0:
            break

    result.reverse()
    if len(result) < n:
        return -1
    return ''.join(map(str, result))

