        degree[node] = len(adj_list[node])
        for neighbor in adj_list[node]:
            if not visited[neighbor]:
                dfs(neighbor, node)

    visited[1] = True
    dfs(1, -1)

    # Add additional edges based on degree
    for node in range(1, n + 1):
        if degree[node] == 0:
            for neighbor in adj_list[node]:
                adj_list[neighbor].append(node)

    return adj_list

def create_tree(n):
    if n == 1:
        return [[]]
    else:
        vertices = range(1, n + 1)
        edges = []
        for i in range(n - 1):
            u, v = (random.randint(1, n) for _ in range(2))
            edges.append((u, v))
        return create_tree(n - 1)[:n - 1] + [(vertices[n - 1], u) for u, v in edges] + [(v, vertices[n - 1]) for u, v in edges]

def compress_tree(t):
    count = 0
    while True:
        edges = []
        for u in range(len(t)):
            if u != t[u]:
                count += 1
                edges.append((t[u], u))
        if count == 1:
            break
        for i, j in edges:
            t[i] = j
        edges = []

    return t

def calculate_probabilities(n, edges):
