        if factory(parent) == idx % n:
            values.append((idx, set(adj_list[idx])))
        else:
            for item in adj_list[idx]:
                location = ((item + factory(item)) % n) // (n + 1)
                if location == idx // n: values.append((idx, set(adj_list[idx])))

    probs = (1 / float(h)) ** h for v in values for h, (v, tree) in enumerate(values)
    probs = [(p / sum(probs)) for p in probs]
