from math import exp

def generate_sq_param(p):
    return 1 - p

def calculate_height(parent, nodes, node_to_height):
    if node_to_height[parent] > 0:
        return node_to_height[parent]

    max_height = 0
    for child in nodes[parent]:
        height = calculate_height(child, nodes, node_to_height)
        probability = generate_sq_param(0.5 - height / sum([1 if i != child else 0 for i in nodes[child]]))
        expected_height = max(0, max_height + height) * probability
        max_height = max(max_height, expected_height)

    node_to_height[parent] = max_height
    return max_height

