from sortedcontainers import SortedList
from typing import List

class SmellDetector:
    def __init__(self, intervals: List[int], changes: List[int]):
        self.intervals = SortedList()
        self.changes = []

        def set_interval(index, start, end):
            if start <= index <= end:
                self.intervals.add((start, end))

        if intervals != []:
            for i in range(len(intervals)):
                set_interval(i, intervals[i][0], intervals[i][1]+1)
                for j in range(i+1, len(intervals)):
                    if intervals[i][1]+1 > intervals[j][0]:
                        if intervals[i][1] > intervals[j][0] and intervals[i][1] < intervals[j][1]:
                            self.intervals.add((intervals[i][1], intervals[j][1]+1))

            for i in range(len(changes)):
                if changes[i] < i+1:
                    for j in range(changes[i]-1, i):
                        self.intervals.add((self.intervals[j][1]+1, self.changes[i]+1))
                else:
                    start = max(self.changes[i]-1, self.intervals[i][0])
                    end = min(self.changes[i]+1, i+1)
                    self.changes.append(self.changes[i]); self.changes.append(end)
                    self.intervals.add((start, end))

                change = changes[i]

                def get_interval(i, start, end):
                    if start <= i <= end:
                        self.interval = SortedList(end*['^'])
                        count = defaultdict(lambda: 0)
                        for j in range(start, end+1, i):
                            count[change] -= 1
                            count[self.changes[j]] += 1
                            self.interval.add((change, 1))
                            self.interval.add((self.changes[j], -1))
                        counts = sorted(self.interval)
                        for j, k in enumerate(counts, counts[0]):
                            self.interval.truncate(j)
                            break
                    return sorted(dict(self.interval).keys())

        for i in range(self.intervals):
            get_interval(i, i, max(i+1, len(self.changes)))

        return sorted(self.interval, key=lambda i: i[0])

