import sys

def can_clear_segment(a, b, n, k):
    if k == 0:
        return a - b + 1 > 0
    else:
        # Reverse the order if k > 0 to start from the end
        if k > 0:
            k, n = n - 1 - k + 1, b - 1
        start, end = a - k, min(n, b)
        return start <= end and end - start + 1 <= k

