def reverse_string(s):
    return s[::-1]

def f(a, i, j):
    return a[i+1:j-1] + reverse_string(a[j:len(a)-1]) + reverse_string(a[0:i])

def find_j(i, b, a):
    for j in range(i+1, len(a)):
        if f(a, i, j) == b: 
            return j
    return -1

def find_i(b, a):
    min_j = 0
    max_j = len(a)-1

    while min_j < max_j:
        mid_j = (min_j + max_j) // 2

        if f(a, mid_j, mid_j) == b:
            return 0
        elif f(a, mid_j, mid_j) > b:
            min_j = max(min_j + 1, mid_j + 1)
        else:
            max_j = mid_j

    return min_j

def main():
